function errorText(code:string){return ERRORS[code]||(code.startsWith('price_server_http_')?'سيرفر الأسعار رفض الطلب ('+code.split('_').at(-1)+'). راجع المفاتيح وحالة السيرفر.':code.startsWith('ai_http_')?'خدمة الذكاء الاصطناعي رفضت الطلب ('+code.split('_').at(-1)+'). راجع المفتاح والنموذج والرصيد.':'حدث خطأ في الطلب. حاول مجددًا.');}
async function api(path:string,data?:unknown,signal?:AbortSignal){const r=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),signal,credentials:'same-origin'});let d:any;try{d=await r.json();}catch{throw Object.assign(new Error('service_unavailable'),{code:'service_unavailable'});}if(!r.ok)throw Object.assign(new Error(d.error||'service_unavailable'),{code:d.error,status:r.status});return d;}
const clock=(t:number|null|undefined,seconds=false)=>t?new Date(t*1000).toLocaleTimeString('en-GB',{timeZone:'UTC',hour:'2-digit',minute:'2-digit',...(seconds?{second:'2-digit'}:{})}):'—';
const date=(t:number|null|undefined)=>t?new Date(t*1000).toLocaleDateString('ar',{timeZone:'UTC'}):'—';
