function Status({status}:{status:string}){const labels:Record<string,string>={LIVE:'أسعار متصلة',AUTHORIZED:'جلسة معتمدة',NO_QUOTES:'بانتظار الأسعار',DEMO:'محاكاة',OFFLINE:'غير متصل',UNAUTHORIZED:'بانتظار الجلسة',STALE:'أسعار متأخرة',UNTIMED:'توقيت غير متاح',LOADING:'جارٍ الاتصال',ERROR:'الاتصال متوقف',CSV:'بيانات CSV'};return <span className={'pill '+(status==='LIVE'?'live':status==='DEMO'?'demo':status==='ERROR'?'bad':'')}><span className={'status-dot '+(status==='LIVE'?'live':'')}/>{labels[status]||status}</span>;}
function NoData({title,description}:{title:string;description:string}){return <Empty className="empty-panel"><EmptyHeader><Target size={28}/><EmptyTitle>{title}</EmptyTitle><EmptyDescription>{description}</EmptyDescription></EmptyHeader></Empty>;}
function saveCSV(signals:Signal[],source:string){const columns=['ID','Asset','Direction','Source','Confluence score (not win probability)','Scheduled entry UTC','Observed entry UTC','Entry price','Scheduled exit UTC','Observed exit UTC','Exit price','Result','Comparison amount USD','Payout','Estimated PnL USD','Note'];const iso=(v:number|null|undefined)=>v?new Date(v*1000).toISOString():'';const rows=signals.map(s=>[s.id,s.asset,s.direction,s.source,s.score,iso(s.entry_at),iso(s.entry_observed_at),s.entry_price,iso(s.exit_at),iso(s.exit_observed_at),s.exit_price,s.result,s.amount,s.payout,s.pnl,s.reason]);const escape=(v:unknown)=>'"'+String(v??'').replace(/"/g,'""')+'"';const text='\ufeff'+[columns,...rows].map(r=>r.map(escape).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download='NEXUS-'+source+'-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function ResultsTable({signals}:{signals:Signal[]}){if(!signals.length)return <NoData title="سجل واضح من أول إشارة" description="كل إشارة مكتملة ستظهر هنا بسعر الدخول والخروج وتوقيتهما. لا توجد نتائج مسبقة أو نسبة نجاح مصطنعة."/>;return <div className="table-shell"><Table><TableHeader><TableRow>{['الزوج','الاتجاه','الدخول UTC','سعر الدخول','الخروج UTC','سعر الخروج','النتيجة','الأثر التقديري'].map(h=><TableHead key={h}>{h}</TableHead>)}</TableRow></TableHeader><TableBody>{signals.map(s=><TableRow key={s.id}><TableCell><b dir="ltr">{assetOf(s.asset).label}</b><span className="muted" style={{fontSize:10,display:'block'}}>{s.source==='demo'?'DEMO':'OTC'} · {date(s.created_at)}</span></TableCell><TableCell><span className={'pill '+(s.direction==='CALL'?'good':'bad')}>{s.direction==='CALL'?'↗ صعود':'↘ هبوط'}</span></TableCell><TableCell dir="ltr" title={'موعد الإشارة: '+clock(s.entry_at,true)}>{clock(s.entry_observed_at??s.entry_at,true)}</TableCell><TableCell dir="ltr">{price(s.entry_price)}</TableCell><TableCell dir="ltr" title={'موعد الإشارة: '+clock(s.exit_at,true)}>{clock(s.exit_observed_at??s.exit_at,true)}</TableCell><TableCell dir="ltr">{price(s.exit_price)}</TableCell><TableCell><span className={'result-badge result-'+s.result} title={s.reason}>{s.result==='UNVERIFIED'?'غير متحقق':s.result}</span></TableCell><TableCell dir="ltr">{s.pnl==null?'—':(Number(s.pnl)>0?'+':'')+s.pnl+' $'}</TableCell></TableRow>)}</TableBody></Table></div>;}
